"""Read and write core.liberation/mod_template.sqf, the one file holding every faction template.

Layout:
  <hand-written head: GRLIB_mod_list_west / _east / _name>
  // @index-begin ... // @index-end       generated by template_audit.py --fix
  HPC_templateFiles = createHashMapFromArray [
  // @template A3_BLU\\classnames_west.sqf
  ["a3_blu\\classnames_west.sqf", {
  <the template file's code>
  }],
  ...
  ];

A template "file" is one entry; F_getTemplateFile runs it as [_args] call <code>.
Keys are lower case; the @template marker keeps the original spelling for tools.
"""
import pathlib
import re

PACK = 'mod_template.sqf'
FILES_START = 'HPC_templateFiles = createHashMapFromArray ['
MARK = '// @template '
INDEX_BEGIN = '// @index-begin'
INDEX_END = '// @index-end'


def read_pack(root):
    """-> (head, index, files): head text, index text and {original path: code}, in file order."""
    # git (core.autocrlf) may check the file out with CRLF line endings
    text = (pathlib.Path(root) / PACK).read_text(encoding='utf-8-sig').replace('\r\n', '\n')
    head, _, rest = text.partition(FILES_START)
    index = ''
    if INDEX_BEGIN in head:
        before, _, after = head.partition(INDEX_BEGIN)
        index, _, after = after.partition(INDEX_END)
        head = before + after
        index = index.strip('\n')
    files = {}
    for chunk in rest.split('\n' + MARK)[1:]:
        name, _, body = chunk.partition('\n')
        body = body.partition(', {\n')[2]
        end = body.rfind('\n}]')
        files[name.strip()] = body[:end]
    return head.rstrip('\n') + '\n', index, files


def write_pack(root, head, index, files):
    out = [head.rstrip('\n'), '', INDEX_BEGIN, index.strip('\n'), INDEX_END, '', FILES_START]
    entries = []
    for name, code in files.items():
        key = name.lower().replace('/', '\\')
        entries.append(f'{MARK}{name}\n["{key}", {{\n{code.rstrip()}\n}}]')
    out.append(',\n'.join(entries))
    out.append('];\n')
    (pathlib.Path(root) / PACK).write_text('\n'.join(out), encoding='utf-8', newline='\n')


def templates(files):
    """{template name: {file name in the template: path key}} (names keep their spelling)."""
    out = {}
    for name in files:
        parts = re.split(r'[\\/]', name, maxsplit=1)
        if len(parts) == 2:
            out.setdefault(parts[0], {})[parts[1].lower()] = name
    return out
